event.testPatch:
test("single select reset", async ({ page }) => {
  await page.goto("fixtures/dom/selects");
  const select = page.locator("select").first();
  await select.selectOption("baz");
  await expect(select).toHaveValue("baz");
  await page.getByRole("button", { name: /reset/i }).click();
  await expect(select).not.toHaveValue("baz");
});

test('multiple select reset', async ({ page }) => {
  await page.goto('/fixtures/dom/selects');
  const sel = page.locator('select[multiple]');
  await sel.selectOption(['bar']);
  await expect(sel).toHaveValues(['bar']);
  await page.getByRole('button', { name: /reset/i }).click();
  await expect(sel).toHaveValues([]);
});
